/* Pursuer self-boost (entities/units/enemies/pursuer/pursuer.gd).
 * Rows cover exactly the scenes whose ROOT script is pursuer.gd
 * (pursuer.tscn, dlc_1/viperfish.tscn); a kind with max_boosts 0 has
 * no BoostTimer.  cooldown/initial_cd are seconds, speed is the flat
 * bonus_speed added per boost, dmg_pct the percent modifier
 * reset_damage_stat receives as damage_on_boost * nb_times_boosted,
 * reset_on_hit is reset_nb_times_boosted_on_hit.  initial_cd is the
 * BoostTimer's scene wait_time (autostart calls start() at the child's
 * _ready, before the root script sets wait_time = boost_cooldown, and
 * set_wait_time never touches time_left), cooldown the value every
 * later reload uses.  pursuer.gd's size_on_boost /
 * change_movement_behavior_after_x_boosts branches are NOT modelled:
 * the campaign pursuer sets size 0 and change -1 (inert); only the DLC
 * viperfish sets them, and the shared core has no per-slot geometry
 * scale or alternate MovementBehavior node. */
typedef struct {
    float cooldown;            /* boost_cooldown (s) */
    float initial_cd;          /* BoostTimer wait_time at autostart (s) */
    float speed;               /* speed_on_boost (flat bonus_speed) */
    unsigned char max_boosts;  /* max_boosts (0 = no BoostTimer) */
    unsigned char dmg_pct;     /* damage_on_boost (percent per boost) */
    unsigned char reset_on_hit;/* reset_nb_times_boosted_on_hit */
    float size;                /* size_on_boost: +0.25*size per boost to
                                * every Collision/Hurtbox/Hitbox shape scale */
    short change_after;        /* change_movement_behavior_after_x_boosts (-1 none) */
    float bonus_on_change;     /* bonus_speed_on_change_movement_behavior (flat) */
} BtSelfBoost;
