/* Item-granted extra groups (ExtraEnemyEffect.extra_group_data, e.g. the
 * bait item).  BtItemEff.extra_group holds the ORDINAL into this table;
 * the core resolves BT_ITEM_EXTRA_GROUPS[ordinal][zone] to a BT_GROUPS
 * row.  One row per zone (like the DLC all-zone groups) so each copy's
 * unit span stays inside its own zone slice; wave_manager.gd:114-121
 * appends the resolved group `BtItemEff.value` times to the next wave's
 * group list.  Ordinals are stable: paths sorted lexically. */
#define BT_NITEM_EXTRA_GROUPS 1
BT_TABLE unsigned short BT_ITEM_EXTRA_GROUPS[BT_NITEM_EXTRA_GROUPS][BT_ZONES] = {
    { 300, 301 },  /* [0] res://zones/common/bait/group_bait.tres  <- res://items/all/bait/bait_effect_2.tres */
};
